//! Twelve preregistered public original-View A/B pairs; no candidate focus design.
#![cfg(target_os="macos")]
#[path="support/coretext.rs"] mod coretext;
use tekes_ui_controls::{BarChart,ChartDatum,ButtonTextRenderer,ButtonTextAlign,ControlKey,collections_view::{ChartView,CollectionEvent}};
use tekes_ui_scene::{Rect,Scene,Size,Point,Primitive};
use tekes_ui_tokens::{Theme,Palette,Rgba,proposal};
fn rect(r:Rect)->[f32;4]{[r.min_x(),r.min_y(),r.size.width,r.size.height]}
fn read_rect(v:&serde_json::Value)->Rect{Rect::new(v[0].as_f64().unwrap() as f32,v[1].as_f64().unwrap() as f32,v[2].as_f64().unwrap() as f32,v[3].as_f64().unwrap() as f32)}
fn rgb(c:Rgba)->[u8;4]{[(c.r*255.).round() as u8,(c.g*255.).round() as u8,(c.b*255.).round() as u8,(c.a*255.).round() as u8]}
struct Text{inner:coretext::Text,draws:Vec<serde_json::Value>,measures:Vec<serde_json::Value>,channels:Vec<(usize,usize,&'static str)>}
impl ButtonTextRenderer for Text{
 fn backing_scale(&self)->f32{self.inner.backing}
 fn measure(&mut self,s:&str,r:proposal::TextRole,w:f32)->Size{let z=self.inner.measure(s,r,w);self.measures.push(serde_json::json!({"text":s,"width":w,"height":z.height}));z}
 fn draw(&mut self,scene:&mut Scene,s:&str,r:proposal::TextRole,f:Rect,a:ButtonTextAlign,c:Rgba){let channel=if self.draws.len().is_multiple_of(2){"V"}else{"C"};let start=scene.primitives().len();self.inner.draw(scene,s,r,f,a,c);let end=scene.primitives().len();self.channels.push((start,end,channel));self.draws.push(serde_json::json!({"text":s,"channel":channel,"frame":rect(f),"color":rgb(c),"primitive_start":start,"primitive_end":end}));}
}
#[test]
#[ignore="explicit actual GPU approved extension twelve only"]
fn original_layout_extension_twelve(){
 let plan:serde_json::Value=serde_json::from_slice(&std::fs::read(std::env::var_os("ISSUE115_PLAN").unwrap()).unwrap()).unwrap();let out=std::path::PathBuf::from(std::env::var_os("ISSUE115_OUT").unwrap());std::fs::create_dir_all(&out).unwrap();let mut gpu=tekes_ui_render::Renderer::new_headless().unwrap();let mut cases=vec![];
 let theme_lane=std::env::var("ISSUE115_THEME").unwrap();
 for c in plan["cases"].as_array().unwrap().iter().filter(|c|c["theme"].as_str().unwrap()==theme_lane){
 let count=c["count"].as_u64().unwrap() as usize;let values=c["values"].as_array().unwrap();let mut m=BarChart::new((0..count).map(|i|ChartDatum::new(c["label"].as_str().unwrap(),values[i%values.len()].as_f64().unwrap())).collect());m.select(2);let mut view=ChartView::new();let mut text=Text{inner:coretext::Text::new(c["scale"].as_f64().unwrap() as f32),draws:vec![],measures:vec![],channels:vec![]};let backing=c["backing"].as_f64().unwrap() as f32;text.inner.backing=backing;let theme=Theme::ALL[c["mode"].as_u64().unwrap() as usize];let palette=if theme_lane=="external"{Palette::for_theme_definition(theme,"external-inputs").unwrap()}else{Palette::from(theme)};let frame=read_rect(&c["frame"]);let clip=if c["clip"].is_null(){None}else{Some(read_rect(&c["clip"]))};let mut scene=Scene::new();let l=view.render(&mut scene,&mut text,&mut m,frame,clip,palette,c["scale"].as_f64().unwrap() as f32);let ground=tekes_ui_tokens::surface_palette::resolve_surface(palette,"canvas","content","rest").unwrap().background;
 let size=((512.*backing) as u32,(280.*backing) as u32);let key=c["key"].as_str().unwrap();let image=gpu.render_to_rgba8(&scene,&mut text.inner.atlas,size,backing,ground).unwrap();std::fs::write(out.join(format!("{key}.rgba8")),image).unwrap();
 let mark=palette.color("c-chart-series-1").unwrap();let selection=palette.color("row-selection").unwrap();let baseline=palette.color("separator").unwrap();
 for channel in ["V","C","N","M","S","B"]{let mut oracle=Scene::new();for (i,p) in scene.primitives().iter().enumerate(){let keep=match p{Primitive::PushClip(_)|Primitive::PopClip=>true,Primitive::Glyphs(_)=>if channel=="N" {text.draws.iter().enumerate().any(|(j,d)|j%2==0&&m.data()[j/2].value<0.&&i>=d["primitive_start"].as_u64().unwrap() as usize&&i<(d["primitive_end"].as_u64().unwrap() as usize))}else{text.channels.iter().any(|(a,b,k)|i>=*a&&i<*b&&*k==channel)},Primitive::Quad(q)=>match channel{"M"=>q.fill==mark,"S"=>q.fill==selection,"B"=>q.fill==baseline,_=>false},_=>false};if keep{oracle.push(p.clone());}}let image=gpu.render_to_rgba8(&oracle,&mut text.inner.atlas,size,backing,Rgba::new(0.,0.,0.,0.)).unwrap();std::fs::write(out.join(format!("{key}-{channel}.rgba8")),image).unwrap();}
 let mut hits=vec![];for y in (0..280).step_by(16){for x in (0..512).step_by(16){let p=Point::new(x as f32,y as f32);let expected=l.geometry.bars.iter().find(|b|l.visible.and_then(|v|b.rect.inset(-6.).intersection(&v)).is_some_and(|r|r.contains(p))).map(|b|b.index);let mut mm=m.clone();let mut vv=view.clone();let moved=vv.pointer_move(p,&mut mm);let event=vv.pointer_down(p,&mut mm);assert_eq!(mm.hovered(),expected);assert_eq!(mm.selected(),expected.or(m.selected()));assert_eq!(matches!(event,CollectionEvent::Ignored),expected.is_none());hits.push(serde_json::json!({"point":[x,y],"expected":expected,"selected":mm.selected(),"hovered":mm.hovered(),"down":format!("{event:?}"),"move_changed":moved}));}}
 let mut keys=vec![];for k in [ControlKey::Left,ControlKey::Right,ControlKey::Down,ControlKey::Up,ControlKey::Home,ControlKey::End]{let mut mm=m.clone();let mut vv=view.clone();vv.focus(true,&mut mm);let e=vv.key(k,true,&mut mm);keys.push(serde_json::json!({"key":format!("{k:?}"),"event":format!("{e:?}"),"selected":mm.selected(),"focus_visible":mm.focus_visible()}));}
 let bars=l.geometry.bars.iter().map(|b|serde_json::json!({"index":b.index,"label":b.label,"value":b.value,"rect":rect(b.rect),"value_label":rect(b.value_label),"category":rect(b.category_label),"selected":b.selected})).collect::<Vec<_>>();let prims=scene.primitives().iter().map(|p|match p{Primitive::Quad(q)=>serde_json::json!({"type":"quad","rect":rect(q.rect),"fill":rgb(q.fill),"border":rgb(q.border_color),"border_width":q.border_width}),Primitive::Glyphs(g)=>serde_json::json!({"type":"glyphs","color":rgb(g.color),"glyphs":g.glyphs.iter().map(|v|serde_json::json!({"origin":[v.origin.x,v.origin.y],"atlas":[v.glyph.page,v.glyph.x,v.glyph.y,v.glyph.width,v.glyph.height],"bearing":[v.glyph.left,v.glyph.top],"format":format!("{:?}",v.glyph.format)})).collect::<Vec<_>>()}),Primitive::PushClip(r)=>serde_json::json!({"type":"pushclip","rect":rect(*r)}),Primitive::PopClip=>serde_json::json!({"type":"popclip"}),_=>serde_json::json!({"type":"other"})}).collect::<Vec<_>>();
 cases.push(serde_json::json!({"key":key,"theme":theme_lane,"expect":c["expect"],"size":[size.0,size.1],"backing":backing,"frame":rect(frame),"visible":l.visible.map(rect),"plot":rect(l.geometry.plot),"baseline":l.geometry.baseline,"bars":bars,"selected":m.selected(),"data":m.data().iter().map(|d|serde_json::json!({"label":d.label,"value":d.value,"value_bits":format!("{:016x}",d.value.to_bits())})).collect::<Vec<_>>(),"draws":text.draws,"measures":text.measures,"primitives":prims,"hits":hits,"keys":keys,"colors":{"P":rgb(ground),"V":rgb(palette.color("primary-text").unwrap()),"C":rgb(palette.color("secondary-text").unwrap()),"S":rgb(selection),"M":rgb(mark),"B":rgb(baseline)},"ground":rgb(ground)}));
 }
 std::fs::write(out.join("cases.json"),serde_json::to_vec_pretty(&cases).unwrap()).unwrap();
}
